function clientCampaignAnalytics(){const report=data.clientCampaigns,brands=report?.brands||{},b=brands[campaignBrand],w=b?.windows?.[performancePeriod],tot=w?.totals||{};const chosen=arr(w?.campaigns).find(c=>c.id===campaignPick);return `<div class="client-report-tabs" role="group" aria-label="Campaign business">${['leadflow','premier','scott'].map(k=>`<button data-campaign-brand="${k}" aria-pressed="${campaignBrand===k}">${esc(brands[k]?.label||({leadflow:'The LeadFlow Pro',premier:'Premier Dental Academy',scott:'Scott · O-L Guy Farms'})[k])}</button>`).join('')}</div>${campaignBrand==='premier'?premierReporting():''}${b?.status!=='available'?empty(b?.label||'Client report unavailable',b?.reason||'Verified reporting access is not connected.'): `<p class="source-note">${esc(b.reason)} · ${esc(w?.period?.start)}–${esc(w?.period?.end)}</p><div class="money-overview">${moneyTile('Ad spend',typeof tot.spend==='number'?tot.spend*100:null,'Campaign-scoped Meta spend',2)}<article class="money-tile"><span>Meta reported leads</span><strong>${num(tot.leads)}</strong><small>Canonical lead action · unique customers separate</small></article>${moneyTile('Cost per lead',typeof tot.cpl==='number'?tot.cpl*100:null,'Spend ÷ Meta leads',2)}${moneyTile('Cost per acquisition',typeof tot.cac==='number'?tot.cac*100:null,'New paying-customer attribution not joined',2)}</div><div class="money-charts">${panel('Spend by campaign','Click a legend to inspect the campaign',sliceChart(arr(w?.campaigns).map(c=>({id:c.id,label:c.name,value:c.spend})),{label:'Ad spend',format:v=>dollars(v*100,2),selected:campaignPick}))}${panel('Campaign in focus','Measured results · existing status',chosen?`<div class="campaign-focus"><h3>${esc(chosen.name)}</h3>${badge(chosen.status)}<dl><div><dt>Spend</dt><dd>${esc(dollars(chosen.spend*100,2))}</dd></div><div><dt>Leads</dt><dd>${num(chosen.leads)}</dd></div><div><dt>CPL</dt><dd>${esc(dollars(typeof chosen.cpl==='number'?chosen.cpl*100:null,2))}</dd></div></dl></div>`:empty('Select a campaign','Click the chart legend or a campaign row below.'))}</div><div class="campaign-table">${arr(w?.campaigns).map(c=>`<button data-chart-campaign="${esc(c.id)}" class="${campaignPick===c.id?'selected':''}"><span><strong>${esc(c.name)}</strong><small>${esc(c.status)}</small></span><span>${esc(dollars(c.spend*100,2))}<small>Spend</small></span><span>${num(c.leads)}<small>Leads</small></span><span>${esc(dollars(typeof c.cpl==='number'?c.cpl*100:null,2))}<small>CPL</small></span></button>`).join('')}</div>`}<details class="metric-method"><summary>Cost per acquisition &amp; scope</summary><p>${esc(report?.acquisitionDefinition||'Acquisition requires attributed new paying customers, not lead counts.')}</p><p>Client accounts are separate from LeadFlow agency campaigns that use Scott or Premier footage.</p></details><p class="source-note">${esc(stamp(report?.observedAt))} · Existing campaign states are observed only.</p>`;}
function organisedAnalytics(){return heading('LEADFLOW · ANALYTICS','See the detail when you need it.','Campaigns, revenue and outcomes, separated by source and business.')+`<div class="analytics-tabs" role="group" aria-label="Analytics section">${[['campaigns','Campaigns'],['money','Money'],['activity','Sales & activity'],['sources','Website & sources'],['context','Business context']].map(([id,label])=>`<button data-analytics-tab="${id}" aria-pressed="${analyticsTab===id}">${label}</button>`).join('')}</div>${['campaigns','activity'].includes(analyticsTab)?`<div class="period-selector" role="group" aria-label="Performance period"><button data-performance-period="7" aria-pressed="${performancePeriod==='7'}">7 days</button><button data-performance-period="28" aria-pressed="${performancePeriod==='28'}">28 days</button></div>`:''}${analyticsTab==='campaigns'?clientCampaignAnalytics():analyticsTab==='money'?moneyAnalytics():analyticsTab==='activity'?performancePanels():analyticsTab==='context'?journeyPanel()+fieldyCoverage()+infrastructurePanel():sourceAnalytics()}`;}
