function route(){const [raw,params]=location.hash.slice(1).split('?');const next=Object.hasOwn(names,raw)?raw:'today';selectedRecord=next==='library'?(new URLSearchParams(params).get('record')||''):'';if(next!==activeRoute){query='';owner='all';bucket=new URLSearchParams(params).get('status')||'all';activeRoute=next;window.scrollTo(0,0);}document.querySelector('#crumb').textContent=names[next];document.title=`${names[next]} · LeadFlow`;document.querySelectorAll('[data-route]').forEach(a=>{const on=a.dataset.route===next;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});tools.hidden=next!=='tools';view.hidden=next==='tools';closeNav();if(next==='tools')return;if(!data){view.innerHTML=heading('LEADFLOW WORKSPACE',loadError?'Unable to load your workspace':'Getting your workspace ready…',loadError||'Reading the latest available business sources.')+(loadError?'<button class="button" id="retry">Try again</button>':'<div class="loading-grid"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>');return;}view.innerHTML=({today,work,clients,marketing,library,plan,leads,connections}[next]||today)();filterResults();}
function filterResults(){const el=document.querySelector('#filtered-results');if(el)el.innerHTML=activeRoute==='work'?workResults():libraryResults();}
async function load(){if(loading)return;loading=true;document.querySelector('#refresh').disabled=true;const conn=document.querySelector('#connection');conn.textContent='Refreshing sources';const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),20000);try{const response=await fetch(`${root.dataset.base}/api/workspace-overview`,{credentials:'same-origin',cache:'no-store',signal:abort.signal});if(!response.ok)throw new Error(response.status===401?'Your session has expired. Open the Hub to sign in again.':'Business sources could not be loaded. Try refreshing.');data=await response.json();lastSuccessfulLoad=Date.now();updateBranding();loadError='';const sourceWarnings=arr(data.errors).length||arr(data.integrations).some(i=>i.status&&!['available','live','restricted'].includes(i.status))||data.performance?.status==='stale';conn.textContent=sourceWarnings?'Some sources need attention':'Sources loaded';document.querySelector('#page-loaded').textContent=`Loaded ${stamp(data.generatedAt)}`;conn.classList.toggle('ready',!sourceWarnings);document.querySelector('#work-count')?.replaceChildren(document.createTextNode(data.work?.status==='available'?num(activeCount(data.work?.counts)):''));route();}catch(error){loadError=error.name==='AbortError'?'The request took too long. Try refreshing.':error.message;conn.textContent='Refresh failed';conn.classList.remove('ready');if(!data)route();else{let notice=document.querySelector('#refresh-error');if(!notice){notice=document.createElement('div');notice.id='refresh-error';notice.className='notice';view.prepend(notice);}notice.textContent=`${loadError} Previously loaded data remains visible.`;}}finally{clearTimeout(timeout);loading=false;document.querySelector('#refresh').disabled=false;}}
function detail(id){const t=tasks().find(t=>String(t.id)===id);if(!t)return;lastFocus=document.activeElement;document.querySelector('#task-detail').innerHTML=`<div class="detail-head"><div><p class="eyebrow">REVIEWED WORK ITEM</p>${badge(t.statusLabel||t.status||t.bucket,t.bucket)}</div><button id="close-task" class="icon-button" aria-label="Close task details">×</button></div><div class="detail-body"><h2 id="task-title">${esc(t.title)}</h2><dl>${[['Owner',ownerLabel(t)],['Priority',t.priority||'Not specified'],['Category',t.category||'Business work'],['Business / target',t.target||'Not specified']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="next-action"><h3>Next action</h3><p>${esc(t.nextAction||'No next action has been recorded.')}</p></div><div class="detail-links">${arr(t.links).filter(l=>safeurl(l.url)).map(l=>`<a class="button" href="${safeurl(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label||'Open related resource')} ↗</a>`).join('')}</div><p class="result-count">Reviewed work record. Status updates happen in the source workflow.</p></div>`;document.querySelector('#task-dialog').showModal();document.querySelector('#close-task').focus();}
function connectionDetails(){
 lastFocus=document.activeElement;
 const entries=Array.isArray(data?.integrations)?data.integrations:[];
 document.querySelector('#task-detail').innerHTML=`<div class="detail-head"><div><p class="eyebrow">LEADFLOW WORKSPACE</p><h2 id="task-title">Connection status</h2></div><button id="close-task" class="icon-button" aria-label="Close connection status">×</button></div><div class="detail-body"><p class="source-note">These statuses describe this LeadFlow workspace and its current sources.</p>${entries.length?entries.map(i=>`<div class="mini-row"><div><strong>${esc(i.name)}</strong><small>${esc(i.reason)}${i.checkedAt?' · Checked '+esc(stamp(i.checkedAt)):''}</small></div>${badge(i.statusLabel||sourceLabel(i.status),['live','available'].includes(i.status)?'good':'warn')}</div>`).join(''):empty('Status unavailable','Refresh the workspace to load the current connections.')}</div>`;
 document.querySelector('#task-dialog').showModal();document.querySelector('#close-task').focus();
}
