document.addEventListener('click',e=>{const week=e.target.closest('[data-proposal-week]');if(week){proposalWeekOffset=week.dataset.proposalWeek==='today'?0:proposalWeekOffset+Number(week.dataset.proposalWeek);proposalDay='';route();}const day=e.target.closest('[data-proposal-day]');if(day){proposalDay=day.dataset.proposalDay;route();document.querySelector(`[data-proposal-day="${proposalDay}"]`)?.focus();}const selected=e.target.closest('[data-proposal-select]');if(selected){const day=selected.dataset.proposalSelect;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const weekday=new Date(today+'T12:00:00Z').getUTCDay();const monday=datePlus(today,-((weekday+6)%7));proposalWeekOffset=Math.floor((Date.parse(day+'T12:00:00Z')-Date.parse(monday+'T12:00:00Z'))/(7*86400000));proposalDay=day;route();document.querySelector('#today-proposals')?.scrollIntoView({block:'start'});}});
