 const syncViewport=()=>{try{const frame=parent.document.querySelector('iframe.lf-admin-owner-frame');const top=Math.max(18,-(frame?.getBoundingClientRect().top||0)+18);document.documentElement.style.setProperty('--native-dialog-top',top+'px');document.documentElement.style.setProperty('--native-viewport-height',Math.max(300,parent.innerHeight-70)+'px');}catch{}};
